import { useMemo, useRef } from 'react'
import { useLang } from '../lib/i18n'
import { ScrollTrigger, clamp01, easeInOut, lerp, prefersReduced, rng, useCanvas, useGsap } from '../lib/gsap'
import { ui } from '../content/ui'
import { Eyebrow, Lines } from '../components/Brand'

/**
 * "We engineer them": seven independent signals enter, and as the reader scrolls
 * they settle into one connected system with a single core.
 */
export function Belief() {
  const { tr, lang, rtl } = useLang()
  const root = useRef<HTMLElement>(null)
  const progress = useRef(prefersReduced() ? 1 : 0)

  useGsap(root, () => {
    if (prefersReduced()) return
    ScrollTrigger.create({
      trigger: root.current,
      start: 'top 60%',
      end: 'bottom bottom',
      onUpdate: (s) => (progress.current = s.progress),
    })
  })

  const seeds = useMemo(() => {
    const r = rng(11)
    return ui.belief.signals.map((_, i) => ({
      sx: r() * 2 - 1,
      sy: r() * 2 - 1,
      ph: r() * Math.PI * 2,
      edge: i % 4,
      th: 0.38 + (i / 7) * 0.3,
    }))
  }, [])

  const canvas = useCanvas(
    (ctx, w, h, t) => {
      const p = progress.current
      const mobile = w < 900
      const cx = mobile ? w * 0.5 : w * (rtl ? 0.3 : 0.7)
      const cy = mobile ? h * 0.74 : h * 0.52
      const R = mobile ? Math.min(w * 0.36, h * 0.19) : Math.min(w * 0.17, h * 0.31)
      const e = easeInOut(clamp01((p - 0.08) / 0.55))
      ctx.clearRect(0, 0, w, h)

      const n = seeds.length
      const pts = seeds.map((s, i) => {
        const a = -Math.PI / 2 + (i / n) * Math.PI * 2 + t * 0.06 * e
        const fx = cx + Math.cos(a) * R
        const fy = cy + Math.sin(a) * R * (mobile ? 0.92 : 1)
        const spreadX = mobile ? w * 0.42 : w * 0.24
        const spreadY = mobile ? h * 0.22 : h * 0.4
        const hx = cx + s.sx * spreadX + Math.sin(t * 0.5 + s.ph) * 14
        const hy = cy + s.sy * spreadY + Math.cos(t * 0.4 + s.ph * 1.7) * 14
        return { x: lerp(hx, fx, e), y: lerp(hy, fy, e), s }
      })

      // Entry trails: each signal arrives from its own edge, alone.
      const trail = 1 - clamp01(p / 0.4)
      if (trail > 0.01) {
        pts.forEach(({ x, y, s }) => {
          const tx = s.edge === 0 ? x - w : s.edge === 2 ? x + w : x
          const ty = s.edge === 1 ? y - h : s.edge === 3 ? y + h : y
          const g = ctx.createLinearGradient(x, y, lerp(x, tx, 0.35), lerp(y, ty, 0.35))
          g.addColorStop(0, `rgba(255,255,255,${0.35 * trail})`)
          g.addColorStop(1, 'rgba(255,255,255,0)')
          ctx.strokeStyle = g
          ctx.lineWidth = 1
          ctx.beginPath()
          ctx.moveTo(x, y)
          ctx.lineTo(tx, ty)
          ctx.stroke()
        })
      }

      // Connections draw in one after another: ring first, then spokes to the core.
      const seg = (ax: number, ay: number, bx: number, by: number, k: number, orange: boolean) => {
        if (k <= 0) return
        ctx.strokeStyle = orange ? `rgba(246,98,13,${0.75})` : 'rgba(255,255,255,0.3)'
        ctx.lineWidth = orange ? 1.4 : 1
        ctx.beginPath()
        ctx.moveTo(ax, ay)
        ctx.lineTo(lerp(ax, bx, k), lerp(ay, by, k))
        ctx.stroke()
      }
      pts.forEach((a, i) => {
        const b = pts[(i + 1) % n]
        seg(a.x, a.y, b.x, b.y, clamp01((p - a.s.th) / 0.14), false)
        seg(a.x, a.y, cx, cy, clamp01((p - a.s.th - 0.16) / 0.14), true)
      })

      // Core
      const core = easeInOut(clamp01((p - 0.7) / 0.25))
      if (core > 0) {
        const r = (mobile ? 16 : 24) * core
        const glow = ctx.createRadialGradient(cx, cy, 0, cx, cy, r * 5)
        glow.addColorStop(0, 'rgba(246,98,13,0.45)')
        glow.addColorStop(1, 'rgba(246,98,13,0)')
        ctx.fillStyle = glow
        ctx.beginPath()
        ctx.arc(cx, cy, r * 5, 0, Math.PI * 2)
        ctx.fill()
        const g = ctx.createRadialGradient(cx - r * 0.3, cy - r * 0.35, 0, cx, cy, r)
        g.addColorStop(0, '#FFC296')
        g.addColorStop(0.45, '#F6620D')
        g.addColorStop(1, '#B8430A')
        ctx.fillStyle = g
        ctx.beginPath()
        ctx.arc(cx, cy, r, 0, Math.PI * 2)
        ctx.fill()
        // A pulse runs the ring once the system is whole.
        const u = (t * 0.12) % 1
        const i0 = Math.floor(u * n)
        const k = u * n - i0
        const a = pts[i0]
        const b = pts[(i0 + 1) % n]
        ctx.fillStyle = `rgba(246,98,13,${core})`
        ctx.beginPath()
        ctx.arc(lerp(a.x, b.x, k), lerp(a.y, b.y, k), 3.5, 0, Math.PI * 2)
        ctx.fill()
      }

      // Nodes and labels
      ctx.font = `${lang === 'ar' ? 500 : 500} ${mobile ? 11 : 12}px ${lang === 'ar' ? '"Noto Kufi Arabic Variable"' : '"Montserrat Variable"'}, sans-serif`
      ctx.textBaseline = 'middle'
      pts.forEach(({ x, y }, i) => {
        ctx.fillStyle = '#fff'
        ctx.beginPath()
        ctx.arc(x, y, 3.5, 0, Math.PI * 2)
        ctx.fill()
        ctx.strokeStyle = 'rgba(255,255,255,0.25)'
        ctx.beginPath()
        ctx.arc(x, y, 9, 0, Math.PI * 2)
        ctx.stroke()
        const label = lang === 'ar' ? ui.belief.signals[i].ar : ui.belief.signals[i].en.toUpperCase()
        const right = x >= cx
        ctx.textAlign = right ? 'left' : 'right'
        ctx.fillStyle = 'rgba(255,255,255,0.72)'
        if (lang === 'en') (ctx as unknown as { letterSpacing: string }).letterSpacing = '2px'
        ctx.fillText(label, x + (right ? 18 : -18), y)
      })
    },
    [lang, rtl, seeds],
  )

  return (
    // <section ref={root} className="scrolly" style={{ ['--scrolly-h' as string]: '230vh' }}>
    //   <div className="scrolly-pin">
    //     <canvas ref={canvas} className="absolute inset-0 h-full w-full" aria-hidden="true" />
    //     <div className="wrap relative flex h-full flex-col justify-start pt-28 lg:justify-center lg:pt-0">
    //       <div className="lg:max-w-[50%]">
    //         <Eyebrow className="mb-6 text-white/70">{tr(ui.belief.eyebrow)}</Eyebrow>
    //         <Lines
    //           className="t-title lg:!text-[clamp(2.2rem,4.4vw,4.6rem)]"
    //           lines={[
    //             <span className="font-light">{tr(ui.belief.l1)}</span>,
    //             <>
    //               {tr(ui.belief.l2a)}
    //               <span className="text-signal">{tr(ui.belief.l2b)}</span>
    //             </>,
    //           ]}
    //         />
    //         <p className="mt-6 max-w-[44ch] font-medium lg:mt-9 lg:text-lg" data-reveal="up">
    //           {tr(ui.belief.p1)}
    //         </p>
    //         <p className="muted mt-3 max-w-[50ch] text-sm leading-relaxed lg:text-base rtl:leading-loose" data-reveal="up">
    //           {tr(ui.belief.p2)}
    //         </p>
    //       </div>
    //     </div>
    //   </div>
    // </section>
  )
}
